INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Marina Beach', 'Chennai', 'Beach', 13.0475, 80.2824, 3000, 'World longest natural urban beach and historic promenade.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Kapaleeshwarar Temple', 'Chennai', 'Religious', 13.0334, 80.2699, 1200, '7th century Dravidian architectural temple dedicated to Lord Shiva.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Fort St. George', 'Chennai', 'Historical', 13.0797, 80.2872, 800, 'First English fortress in India founded in 1644.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Guindy National Park', 'Chennai', 'Park', 13.0067, 80.2206, 900, 'Protected national park within city limits hosting blackbucks.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('San Thome Basilica', 'Chennai', 'Religious', 13.0337, 80.2782, 1000, 'Neo-Gothic church built over the tomb of Saint Thomas.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Government Museum Chennai', 'Chennai', 'Museum', 13.0694, 80.2568, 1100, 'Human history and culture museum established in 1851.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Elliot Beach', 'Chennai', 'Beach', 12.9998, 80.2709, 1800, 'Scenic southern end of the Marina coastline in Besant Nagar.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Lalbagh Botanical Garden', 'Bengaluru', 'Park', 12.9507, 77.5848, 2500, 'Century-old botanical garden with iconic glass house.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Cubbon Park', 'Bengaluru', 'Park', 12.9764, 77.5929, 2800, 'Major green landmark lung of the central administrative area.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Bangalore Palace', 'Bengaluru', 'Historical', 12.9988, 77.5921, 1400, 'Tudor-style royal estate inspired by Windsor Castle.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Bannerghatta Biological Park', 'Bengaluru', 'Park', 12.8009, 77.5777, 2000, 'Wildlife sanctuary with safari, zoo, and butterfly park.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('ISKCON Temple Bangalore', 'Bengaluru', 'Religious', 13.0098, 77.5511, 2200, 'One of the largest Hindu temple complexes in the world.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Visvesvaraya Industrial Museum', 'Bengaluru', 'Museum', 12.9752, 77.5963, 1200, 'Interactive science and technology exposition center.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Charminar', 'Hyderabad', 'Historical', 17.3616, 78.4747, 2600, 'Monument and mosque built in 1591 with four grand arches.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Golconda Fort', 'Hyderabad', 'Historical', 17.3833, 78.4011, 2200, 'Medieval fortified citadel renowned for acoustic engineering.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Hussain Sagar Lake', 'Hyderabad', 'Park', 17.4239, 78.4738, 2400, 'Heart-shaped lake featuring monolith Buddha statue.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Salar Jung Museum', 'Hyderabad', 'Museum', 17.3713, 78.4804, 1500, 'Renowned art museum with collections across three continents.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Birla Mandir Hyderabad', 'Hyderabad', 'Religious', 17.4062, 78.4691, 1300, 'White Rajasthani marble temple on Naubat Pahad hill.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Ramoji Film City', 'Hyderabad', 'Park', 17.2543, 78.6808, 4000, 'Integrated film city and tourism recreation resort.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Gateway of India', 'Mumbai', 'Historical', 18.922, 72.8347, 3500, 'Iconic 20th century arch monument overlooking the Arabian Sea.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Marine Drive', 'Mumbai', 'Beach', 18.9432, 72.823, 4000, 'C-shaped concrete boulevard known as the Queen Necklace.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Elephanta Caves', 'Mumbai', 'Historical', 18.9633, 72.9315, 1200, 'UNESCO World Heritage rock-cut cave temples on Gharapuri Island.');
