INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Sanjay Gandhi National Park', 'Mumbai', 'Park', 19.2288, 72.9182, 2500, 'Extensive protected forest hosting ancient Kanheri Caves.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Siddhivinayak Temple', 'Mumbai', 'Religious', 19.0169, 72.8303, 2000, 'Famous Hindu temple consecrated in 1801 dedicated to Lord Ganesha.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Red Fort', 'Delhi', 'Historical', 28.6562, 77.241, 3200, 'Historic fortress palace of the Mughal dynasty in Old Delhi.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Qutub Minar', 'Delhi', 'Historical', 28.5244, 77.1855, 2400, 'Tallest brick minaret in the world surrounded by ancient ruins.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('India Gate', 'Delhi', 'Historical', 28.6129, 77.2295, 3800, 'War memorial arch honoring fallen soldiers along Kartavya Path.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Humayun Tomb', 'Delhi', 'Historical', 28.5933, 77.2507, 1600, 'Magnificent garden tomb precursor to the Taj Mahal.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Lotus Temple', 'Delhi', 'Religious', 28.5535, 77.2588, 2500, 'Bahai House of Worship noted for flowerlike architecture.');
INSERT INTO ATTRACTIONS (attraction_name, city, category, latitude, longitude, capacity, description) VALUES ('Shaniwar Wada', 'Pune', 'Historical', 18.5196, 73.8553, 1800, '18th-century seat of the Peshwa rulers of the Maratha Empire.');
